"""Every number in the notes on one page: amounts, shares, days, periods, fees and penalties.

Each row names the situation it applies to, its starting point or condition, the notes
section it comes from and the cited passage. Rows reuse the manuscripts' anchors, which
build.py verifies against the extracted source text.
"""
from model import p, ref


def row(value, what, basis, part, section, refs):
    return dict(value=p(*value), what=p(*what), basis=p(*basis), part=part, section=section, refs=refs)


def group(key, title, intro, rows):
    return dict(id=key, title=p(*title), intro=p(*intro), rows=rows)


